/* Stuttgart — restrained luxury: obsidian cabin, silver type, chrome hairline. Opaque metal, no glass. */
:root {
  color: var(--cu-color-fg-default);
  background: var(--cu-color-background-default);
  font-family: var(--cu-font-family-sans);
  font-synthesis: none;
  letter-spacing: var(--cu-font-tracking-tight);
  line-height: var(--cu-typography-line-height-body);
}

:root .cu-heading,
:root .cu-navbar__brand,
:root .cu-dialog__title {
  font-weight: var(--cu-font-weight-bold);
  letter-spacing: var(--cu-font-tracking-tight);
}

:root .cu-navbar,
:root .cu-app-shell__header {
  background: var(--cu-color-background-elevated);
  border-block-end: 1px solid var(--cu-color-border-default);
  box-shadow: inset 0 1px 0 color-mix(in srgb, #fff 10%, transparent);
}

:root .cu-navbar {
  border-block-end-color: color-mix(in srgb, var(--cu-color-palette-brand) 42%, var(--cu-color-border-default));
}

:root .cu-tab-bar,
:root .cu-app-shell__sidebar {
  background: var(--cu-color-background-elevated);
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
}

:root .cu-navbar,
:root .cu-dialog__content,
:root .cu-app-shell__header {
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
}

:root .cu-app-shell__main {
  background: var(--cu-color-background-subtle);
}

:root .cu-card {
  background: var(--cu-color-background-elevated);
}

:root .cu-button:focus-visible,
:root .cu-input:focus-visible,
:root .cu-navbar__item:focus-visible,
:root .cu-select__trigger:focus-visible {
  outline-width: 2px;
  outline-offset: 2px;
}

:root .cu-button--outline {
  border-color: var(--cu-color-border-default);
  background: transparent;
}

@media (hover: hover) {
  :root .cu-button--solid:hover:not(:disabled) {
    background: color-mix(in srgb, var(--cu-color-palette-brand) 88%, #000);
  }
}

/* Stuttgart — measured 180ms ease. All bezier points stay in [0, 1] (no overshoot). */
:root .cu-button,
:root .cu-navbar__item,
:root .cu-tab-bar__item,
:root .cu-switch__control,
:root .cu-switch__thumb,
:root .cu-alert,
:root .cu-badge,
:root .cu-input,
:root .cu-select__trigger {
  transition-duration: var(--cu-motion-duration-base);
  transition-timing-function: var(--cu-motion-easing-standard);
}

:root .cu-button,
:root .cu-button:hover,
:root .cu-button:focus-visible,
:root .cu-navbar__item:hover,
:root .cu-tab-bar__item:hover {
  transform: none;
}

:root .cu-button:active {
  transform: none;
}

@media (prefers-reduced-motion: reduce) {
  :root .cu-button,
  :root .cu-navbar__item,
  :root .cu-tab-bar__item,
  :root .cu-switch__control,
  :root .cu-switch__thumb {
    transition-duration: 0.01ms;
  }
}

/* Stuttgart — precise 2/4/6px. Interactive = sm, surfaces = md. No oversized corners. */
:root .cu-button,
:root .cu-badge,
:root .cu-input,
:root .cu-textarea,
:root .cu-select__trigger,
:root .cu-navbar__item,
:root .cu-tag,
:root .cu-search-bar__clear,
:root .cu-search-bar__submit,
:root .cu-checkbox,
:root .cu-switch__control,
:root .cu-switch__thumb {
  border-radius: var(--cu-radius-interactive);
}

:root .cu-card,
:root .cu-alert,
:root .cu-toast,
:root .cu-popover__content,
:root .cu-notification,
:root .cu-code-block,
:root .cu-data-grid,
:root .cu-table {
  border-radius: var(--cu-radius-surface);
}

:root .cu-dialog__content {
  border-radius: var(--cu-radius-surface);
  border-start-start-radius: var(--cu-radius-surface);
  border-start-end-radius: var(--cu-radius-surface);
  border-end-start-radius: var(--cu-radius-surface);
  border-end-end-radius: var(--cu-radius-surface);
}

/* Stuttgart — elevation over border: short metallic shadows, not soft blobs. */
:root .cu-card--elevated,
:root .cu-toast,
:root .cu-popover__content,
:root .cu-select__content,
:root .cu-command-palette {
  box-shadow: var(--cu-shadow-md);
}

:root .cu-dialog__content,
:root .cu-action-sheet {
  box-shadow: var(--cu-shadow-lg);
}

:root .cu-card--outlined {
  box-shadow: var(--cu-shadow-sm);
}

:root .cu-button--solid {
  box-shadow:
    inset 0 1px 0 color-mix(in srgb, #fff 16%, transparent),
    var(--cu-shadow-sm);
}

:root .cu-button--solid:active {
  box-shadow: inset 0 1px 2px color-mix(in srgb, #000 35%, transparent);
}

{
  "radius": {
    "$type": "dimension",
    "sm": { "$value": { "value": 2, "unit": "px" } },
    "md": { "$value": { "value": 4, "unit": "px" } },
    "lg": { "$value": { "value": 6, "unit": "px" } },
    "interactive": { "$value": "{radius.sm}" },
    "surface": { "$value": "{radius.md}" }
  },
  "blur": {
    "$type": "dimension",
    "surface": { "$value": { "value": 0, "unit": "px" } }
  },
  "shadow": {
    "none": { "$value": "none" },
    "sm": {
      "$value": "0 1px 2px color-mix(in srgb, #000 55%, transparent), 0 0 0 1px color-mix(in srgb, #fff 6%, transparent)"
    },
    "md": {
      "$value": "0 4px 12px color-mix(in srgb, #000 48%, transparent), 0 1px 0 color-mix(in srgb, #fff 8%, transparent)"
    },
    "lg": {
      "$value": "0 12px 28px color-mix(in srgb, #000 58%, transparent), 0 0 0 1px color-mix(in srgb, #fff 5%, transparent)"
    }
  },
  "motion": {
    "duration": {
      "$type": "dimension",
      "fast": { "$value": { "value": 120, "unit": "ms" } },
      "base": { "$value": { "value": 180, "unit": "ms" } }
    },
    "easing": {
      "standard": { "$value": "cubic-bezier(0.25, 0.1, 0.25, 1)" }
    }
  },
  "font": {
    "family": {
      "sans": { "$value": "\"Helvetica Neue\", Helvetica, Arial, system-ui, sans-serif" }
    },
    "weight": {
      "semibold": { "$value": 600 },
      "bold": { "$value": 700 }
    },
    "tracking": {
      "tight": { "$value": "-0.015em" }
    }
  },
  "color": {
    "palette": {
      "brand": { "$value": "#bb0a30" },
      "ink": { "$value": "#eceef0" },
      "paper": { "$value": "#0f0f0f" }
    },
    "fg": {
      "default": { "$value": "{color.palette.ink}" },
      "inverse": { "$value": "#f7f7f5" },
      "muted": { "$value": "#9a9ea4" }
    },
    "background": {
      "default": { "$value": "{color.palette.paper}" },
      "inverse": { "$value": "#eceef0" },
      "subtle": { "$value": "#161616" },
      "elevated": { "$value": "#1c1c1e" }
    },
    "border": {
      "default": { "$value": "#3a3d42" }
    }
  },
  "typography": {
    "line-height": {
      "body": { "$value": 1.4 }
    }
  }
}
